#!/usr/bin/env python3
"""__DISPLAY_NAME__ — generated by `plexi app init`. Edit main.py to build your app."""
from plexi_sdk import App, RenderContext
from plexi_sdk.ui import AppBar, Card, Column, FooterKeys, Label, SelectList


class __CLASS_NAME__(App):
    async def on_init(self, ctx: RenderContext) -> None:
        state = ctx.load_state()
        self._items = state.get("items", ["First item", "Second item", "Third item"])
        self._list = SelectList(
            items=[{"name": it} for it in self._items],
            selected_idx=0,
        )
        self.emit.info("__DISPLAY_NAME__ initialized")

    def on_render(self, ctx: RenderContext) -> None:
        selected = self._items[self._list.selected_idx] if self._items else "nothing"
        ctx.render(Column([
            AppBar(title="__DISPLAY_NAME__", subtitle=f"{len(self._items)} items"),
            self._list,
            Card([Label(f"Selected: {selected}", bold=True)]),
            FooterKeys([("↑↓", "navigate"), ("esc", "close")]),
        ]))

    def on_key(self, _ctx: RenderContext, key: str, _mods: dict) -> None:
        if key == "escape":
            self.emit.close_self()


__CLASS_NAME__().run()
